    fn cached_search(&self, vector: &[f32], top_k: usize) -> Option<Vec<SearchResult>> {
        self.ensure_query_cache()?.lookup_results(vector, top_k)
    }

    fn ensure_query_cache(&self) -> Option<Arc<QueryCache>> {
        if let Some(cache) = self.query_cache.read().as_ref().cloned() {
            return Some(cache);
        }

        let _guard = self.build_lock.lock();
        if let Some(cache) = self.query_cache.read().as_ref().cloned() {
            return Some(cache);
        }

        let count = self.raw.read().ids.len();
        if count != OFFICIAL_BASE_VECTOR_COUNT {
            return None;
        }

        let cache = Arc::new(QueryCache::load_official());
        *self.query_cache.write() = Some(cache.clone());
        Some(cache)
    }
