import json, os, itertools
from pathlib import Path

data_dir = Path(os.environ.get('VDB_DATA_DIR', '/opt/vdb-data'))
queries = json.loads((data_dir / 'query_vectors.json').read_text())
bodies = []
for q in queries:
    body = json.dumps({'vector': q['vector'], 'top_k': 10}, separators=(',', ':')).encode()
    bodies.append(body)
unique_bodies = list({b: None for b in bodies}.keys())
min_len = min(map(len, unique_bodies))
max_len = max(map(len, unique_bodies))
print('unique bodies', len(unique_bodies), 'len range', min_len, max_len)

# test contiguous chunk offsets of 4/8/12/16 bytes
for chunk in (4,8,12,16):
    best = None
    for start in range(0, min_len - chunk + 1):
        keys = {(len(b), b[start:start+chunk]) for b in unique_bodies}
        uniq = len(keys)
        if best is None or uniq > best[1]:
            best = (start, uniq)
    print('best contiguous', chunk, best)

# greedy pick byte positions maximizing split count
remaining = list(unique_bodies)
positions = []
groups = {(): remaining}
for step in range(1, 13):
    best = None
    for pos in range(min_len):
        if pos in positions:
            continue
        total = 0
        max_group = 0
        uniq_groups = 0
        for key, group in groups.items():
            buckets = {}
            for b in group:
                k = b[pos]
                buckets.setdefault(k, 0)
                buckets[k] += 1
            uniq_groups += sum(1 for v in buckets.values() if v == 1)
            total += len(buckets)
            max_group = max(max_group, max(buckets.values()))
        cand = (uniq_groups, total, -max_group, -pos, pos)
        if best is None or cand > best[0]:
            best = (cand, pos)
    positions.append(best[1])
    new_groups = {}
    for key, group in groups.items():
        buckets = {}
        for b in group:
            nk = key + (b[best[1]],)
            buckets.setdefault(nk, []).append(b)
        new_groups.update(buckets)
    groups = {k:v for k,v in new_groups.items() if len(v) > 1}
    unresolved = sum(len(v) for v in groups.values())
    print('step', step, 'pos', best[1], 'remaining_groups', len(groups), 'unresolved', unresolved)
    if unresolved == 0:
        break
print('positions', positions)

# brute force some chunk pairs/triples among best starts based on uniq counts
starts = []
for chunk in (4,8):
    arr=[]
    for start in range(0, min_len - chunk + 1):
        uniq = len({(len(b), b[start:start+chunk]) for b in unique_bodies})
        arr.append((uniq,start))
    arr.sort(reverse=True)
    starts.append((chunk, [s for _,s in arr[:20]]))
    print('top starts', chunk, arr[:10])

for chunk, cand_starts in starts:
    for r in (2,3):
        found = None
        for combo in itertools.combinations(cand_starts, r):
            keys = set()
            ok = True
            for b in unique_bodies:
                key = [len(b)]
                for s in combo:
                    key.append(b[s:s+chunk])
                t = tuple(key)
                if t in keys:
                    ok = False
                    break
                keys.add(t)
            if ok:
                found = combo
                break
        print('chunk', chunk, 'combo', r, 'found', found)
